params.command:
$ErrorActionPreference='Stop'
$dest = Join-Path $env:TEMP 'shipit-20260929-0922-agentcontrol-finaltest-6c49852a'
if (Test-Path $dest) { Remove-Item -Recurse -Force $dest }
git clone --no-checkout https://github.com/fengie/mhw-mods.git $dest
git -C $dest fetch origin 6c49852a72ba23d50cfca6ac77b1104c37728aa4
git -C $dest checkout --detach 6c49852a72ba23d50cfca6ac77b1104c37728aa4
$actual = (git -C $dest rev-parse HEAD).Trim()
if ($actual -ne '6c49852a72ba23d50cfca6ac77b1104c37728aa4') { throw "HEAD mismatch: $actual" }
Push-Location (Join-Path $dest 'tools\agent-control')
try {
  node --version
  npm run check
  node --test --test-reporter tap test/*.test.mjs
} finally { Pop-Location }
Write-Output "VERIFIED_HEAD=$actual"
if ((git -C $dest status --porcelain)) { throw 'verification checkout became dirty' }
